:root {
  --bg: #f7f8fa; --card: #fff; --border: #e2e5ea; --text: #1c2230;
  --muted: #6b7280; --accent: #2563eb; --accent-weak: #eef2ff; --danger: #dc2626;
  --radius: 10px; --font-scale: 1;
}
* { box-sizing: border-box; }
body {
  margin: 0; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg); color: var(--text); font-size: calc(16px * var(--font-scale));
}
body[data-text-size="small"] { --font-scale: 0.9; }
body[data-text-size="medium"] { --font-scale: 1; }
body[data-text-size="large"] { --font-scale: 1.15; }

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.app-header {
  display: flex; align-items: center; gap: 1.25rem; padding: 0.75rem 1.25rem;
  background: var(--card); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 10;
  flex-wrap: wrap;
}
.app-header h1 { font-size: 1.15rem; margin: 0; }
.app-header h1 a { color: var(--text); }
.views { display: flex; gap: 1rem; flex: 1; }
.views a.active { font-weight: 600; color: var(--accent); }

button { font: inherit; cursor: pointer; border: 1px solid var(--border); background: var(--card);
  color: var(--text); border-radius: 8px; padding: 0.45rem 0.8rem; }
button.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
button.danger { color: var(--danger); border-color: var(--danger); }
button:hover { filter: brightness(0.97); }

main { max-width: 960px; margin: 0 auto; padding: 1.25rem; }

.toolbar { display: flex; gap: 0.5rem; align-items: center; margin-bottom: 1rem; flex-wrap: wrap; }
.toolbar input[type="search"], .toolbar input[type="text"], select, input[type="number"] {
  font: inherit; padding: 0.45rem 0.6rem; border: 1px solid var(--border); border-radius: 8px; background: #fff;
}
.toolbar input[type="search"] { flex: 1; min-width: 240px; }
.search-error { color: var(--danger); font-size: 0.85rem; margin: 0.25rem 0; }

.bulk-bar { display: flex; gap: 0.5rem; align-items: center; background: var(--accent-weak);
  border: 1px solid var(--border); border-radius: 8px; padding: 0.5rem 0.75rem; margin-bottom: 0.75rem; flex-wrap: wrap; }
.bulk-bar .count { font-weight: 600; }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.6rem; }
.bookmark {
  display: flex; gap: 0.75rem; background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 0.8rem 1rem; align-items: flex-start;
}
.bookmark.selected { outline: 2px solid var(--accent); }
.bookmark .select { margin-top: 0.2rem; }
.bookmark .favicon { width: 20px; height: 20px; border-radius: 4px; flex: none; margin-top: 0.15rem; background: #eee; object-fit: contain; }
.bookmark .body { flex: 1; min-width: 0; }
.bookmark .title { font-weight: 600; display: block; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bookmark .desc { color: var(--muted); font-size: 0.9rem; margin: 0.2rem 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.bookmark .meta { display: flex; gap: 0.4rem; flex-wrap: wrap; align-items: center; font-size: 0.8rem; }
.tag { background: var(--accent-weak); color: var(--accent); border-radius: 999px; padding: 0.1rem 0.55rem; font-size: 0.78rem; }
.badge { font-size: 0.72rem; color: var(--muted); border: 1px solid var(--border); border-radius: 999px; padding: 0.05rem 0.5rem; }
.bookmark .actions { display: flex; gap: 0.3rem; flex: none; }
.bookmark .actions button { padding: 0.25rem 0.5rem; font-size: 0.82rem; }

.empty { text-align: center; color: var(--muted); padding: 3rem 1rem; }
.loading { color: var(--muted); }

.pagination { display: flex; gap: 0.75rem; align-items: center; justify-content: center; margin-top: 1rem; }

/* Modal / form */
.modal-backdrop { position: fixed; inset: 0; background: rgba(15,20,30,0.45); display: flex; align-items: flex-start;
  justify-content: center; padding: 3rem 1rem; z-index: 100; overflow: auto; }
.modal { background: var(--card); border-radius: 12px; padding: 1.5rem; width: min(640px, 100%); }
.modal h2 { margin-top: 0; }
.field { display: flex; flex-direction: column; gap: 0.3rem; margin-bottom: 0.9rem; }
.field label { font-weight: 600; font-size: 0.9rem; }
.field input, .field textarea { font: inherit; padding: 0.5rem 0.6rem; border: 1px solid var(--border); border-radius: 8px; }
.field textarea { min-height: 100px; resize: vertical; }
.field .hint { color: var(--muted); font-size: 0.8rem; }
.form-actions { display: flex; gap: 0.6rem; justify-content: flex-end; margin-top: 0.5rem; }
.form-error { color: var(--danger); }
.note-preview { border: 1px dashed var(--border); border-radius: 8px; padding: 0.5rem 0.75rem; background: #fafbfc; }

/* Tag input with suggestions */
.tag-input { position: relative; }
.tag-chips { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.tag-chips .tag { display: inline-flex; gap: 0.35rem; align-items: center; }
.tag-chips .tag button { border: none; background: none; color: inherit; padding: 0; font-size: 0.9rem; }
.suggestions { position: absolute; z-index: 20; background: #fff; border: 1px solid var(--border); border-radius: 8px;
  margin-top: 2px; list-style: none; padding: 0.25rem; width: 100%; max-height: 180px; overflow: auto; }
.suggestions li { padding: 0.3rem 0.5rem; border-radius: 6px; cursor: pointer; }
.suggestions li:hover, .suggestions li.active { background: var(--accent-weak); }

.filter-tags { display: flex; gap: 0.35rem; flex-wrap: wrap; align-items: center; }
.filter-tags .tag.exclude { background: #fde8e8; color: var(--danger); text-decoration: line-through; }

