.form-actions { display: flex; gap: 0.6rem; justify-content: flex-end; margin-top: 0.5rem; }
.form-error { color: var(--danger); }
.note-preview { border: 1px dashed var(--border); border-radius: 8px; padding: 0.5rem 0.75rem; background: #fafbfc; }

/* Tag input with suggestions */
.tag-input { position: relative; }
.tag-chips { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.tag-chips .tag { display: inline-flex; gap: 0.35rem; align-items: center; }
.tag-chips .tag button { border: none; background: none; color: inherit; padding: 0; font-size: 0.9rem; }
.suggestions { position: absolute; z-index: 20; background: #fff; border: 1px solid var(--border); border-radius: 8px;
  margin-top: 2px; list-style: none; padding: 0.25rem; width: 100%; max-height: 180px; overflow: auto; }
.suggestions li { padding: 0.3rem 0.5rem; border-radius: 6px; cursor: pointer; }
.suggestions li:hover, .suggestions li.active { background: var(--accent-weak); }

.filter-tags { display: flex; gap: 0.35rem; flex-wrap: wrap; align-items: center; }
.filter-tags .tag.exclude { background: #fde8e8; color: var(--danger); text-decoration: line-through; }

