  await expect(page.locator('.empty')).toBeVisible();
  await page.goto('/#/archive');
  await page.locator(`.bookmark[data-id="${b.id}"] button`, { hasText: 'Restore' }).click();
  await page.goto('/');
  await expect(page.locator('.bookmark', { hasText: 'Keeper' })).toBeVisible();
});

